# Find connected components of colored cells (with 4-connectivity)
def get_colored_components(grid):
    h, w = len(grid), len(grid[0])
    colored = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                colored.add((r,c))

    components = []
    visited = set()
    for r in range(h):
        for c in range(w):
            if (r,c) in colored and (r,c) not in visited:
                comp = set()
                q = [(r,c)]
                visited.add((r,c))
                while q:
                    cr, cc = q.pop(0)
                    comp.add((cr,cc))
                    for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                        nr, nc = cr+dr, cc+dc
                        if 0<=nr<h and 0<=nc<w and (nr,nc) in colored and (nr,nc) not in visited:
                            visited.add((nr,nc))
                            q.append((nr,nc))
                components.append(comp)
    return components

