import json

def trace_up_to_hit(grid, pos):
    """Trace up from position until we hit colored cell or edge"""
    r, c = pos
    trace = []
    while True:
        trace.append((r, c))
        if grid[r][c] != 0:
            return trace  # Hit colored
        if r == 0:
            return trace + [(None, None)]  # Hit edge
        r -= 1

