def transform(grid):
    """Fill the component of 0s that touches exactly one boundary edge with 2s."""
    if not grid or not grid[0]:
        return grid

    h, w = len(grid), len(grid[0])
    walls = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                walls.add((r, c))

    # Find all connected components
    components = []
    visited = set()
    for r in range(h):
        for c in range(w):
            if (r, c) not in walls and (r, c) not in visited:
                component = set()
                q = [(r, c)]
                visited.add((r, c))
                while q:
                    cr, cc = q.pop(0)
                    component.add((cr, cc))
                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in walls and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            q.append((nr, nc))
                components.append(component)

    # Find the component touching exactly one boundary
    for comp in components:
        touches_top = any(r == 0 for r, c in comp)
        touches_bottom = any(r == h - 1 for r, c in comp)
        touches_left = any(c == 0 for r, c in comp)
        touches_right = any(c == w - 1 for r, c in comp)
        touch_count = sum([touches_top, touches_bottom, touches_left, touches_right])
        if touch_count == 1:
            for r, c in comp:
                grid[r][c] = 2
            break

    return grid

